package main

import (
	"context"
	"fmt"
	"time"

	"golang.org/x/sys/windows"

	"github.com/anthnel/devdesk/internal/ports"
)

func main() {
	// ── 1. Could K actually terminate the process on each row? ───────────────
	//
	// OpenProcess(PROCESS_TERMINATE) asks the same question TerminateProcess
	// would, and answers it without killing anything. The handle is closed at
	// once.
	first, err := ports.List(context.Background(), false)
	if err != nil {
		fmt.Println("fatal:", err)
		return
	}

	seen := map[string]bool{}
	killable, refused, noPID := 0, 0, 0
	refusedNames := map[string]int{}
	killableNames := map[string]int{}
	for _, s := range first {
		if s.PID == "" {
			noPID++
			continue
		}
		if seen[s.PID] {
			continue
		}
		seen[s.PID] = true
		var pid uint32
		_, _ = fmt.Sscan(s.PID, &pid)
		h, err := windows.OpenProcess(windows.PROCESS_TERMINATE, false, pid)
		if err != nil {
			refused++
			refusedNames[s.Process]++
			continue
		}
		_ = windows.CloseHandle(h)
		killable++
		killableNames[s.Process]++
	}
	fmt.Printf("rows=%d distinct-pids=%d rows-with-no-pid=%d\n", len(first), len(seen), noPID)
	fmt.Printf("PROCESS_TERMINATE granted: %d   refused: %d\n", killable, refused)
	fmt.Println("granted:", killableNames)
	fmt.Println("refused:", refusedNames)

	// ── 2. How much does the table actually move between two refreshes? ──────
	time.Sleep(2 * time.Second)
	second, err := ports.List(context.Background(), false)
	if err != nil {
		fmt.Println("second read failed:", err)
		return
	}

	key := func(s ports.Socket) string {
		return s.Protocol + " " + s.LocalAddr + " " + s.PeerAddr + " " + s.PID
	}
	sameIndex := 0
	n := min(len(first), len(second))
	for i := range n {
		if key(first[i]) == key(second[i]) {
			sameIndex++
		}
	}
	inFirst := map[string]bool{}
	for _, s := range first {
		inFirst[key(s)] = true
	}
	gone, arrived := 0, 0
	inSecond := map[string]bool{}
	for _, s := range second {
		inSecond[key(s)] = true
		if !inFirst[key(s)] {
			arrived++
		}
	}
	for k := range inFirst {
		if !inSecond[k] {
			gone++
		}
	}
	fmt.Printf("\ntwo reads 2s apart: %d -> %d rows; %d/%d indexes still point at the same socket\n",
		len(first), len(second), sameIndex, n)
	fmt.Printf("sockets gone: %d   sockets arrived: %d\n", gone, arrived)

	// Listening sockets only — what the tab is mostly read for.
	countListen := func(ss []ports.Socket) int {
		c := 0
		for _, s := range ss {
			if s.State == "LISTEN" {
				c++
			}
		}
		return c
	}
	fmt.Printf("LISTEN rows: %d -> %d\n", countListen(first), countListen(second))

	// ── 3. What does one read cost? ─────────────────────────────────────────
	t0 := time.Now()
	for range 5 {
		_, _ = ports.List(context.Background(), false)
	}
	fmt.Printf("\none read: %v\n", time.Since(t0)/5)
}

