func main() {
	// ── Interfaces: name, state, addresses, MTU — stdlib ─────────────────────
	ifaces, err := net.Interfaces()
	fmt.Printf("net.Interfaces(): n=%d err=%v\n", len(ifaces), err)
	shown := 0
	for _, i := range ifaces {
		addrs, _ := i.Addrs()
		if len(addrs) == 0 || shown >= 8 {
			continue
		}
		shown++
		var cidrs []string
		for _, a := range addrs {
			cidrs = append(cidrs, a.String())
		}
		state := "DOWN"
		if i.Flags&net.FlagUp != 0 {
			state = "UP"
		}
		if i.Flags&net.FlagLoopback != 0 {
			state = "LOOP"
		}
		fmt.Printf("  %-38s %-5s mtu=%-6d %s\n", i.Name, state, i.MTU, strings.Join(cidrs, " "))
	}

	// ── RX/TX errors — gopsutil ──────────────────────────────────────────────
	counters, err := gnet.IOCounters(true)
	fmt.Printf("\ngopsutil IOCounters(per-nic): n=%d err=%v\n", len(counters), err)
	for i, c := range counters {
		if i >= 6 {
