// Temporary probe: what does removing the depth limit cost, and find?
func TestDepthProbe(t *testing.T) {
	root := os.Getenv("DEPTHPROBE_ROOT")
	if root == "" {
		t.Skip("no root")
	}
	entries, err := os.ReadDir(root)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if !e.IsDir() || isHidden(e.Name(), false) {
			continue
		}
		dir := filepath.Join(root, e.Name())

		t0 := time.Now()
		at3 := detectSubRepoPaths(dir, 3, false)
		d3 := time.Since(t0)

		t0 = time.Now()
		unbounded := detectSubRepoPaths(dir, math.MaxInt, false)
		dInf := time.Since(t0)

		t.Logf("%-24s depth3: %2d repos in %-10v   unbounded: %2d repos in %v",
			e.Name(), len(at3), d3.Round(time.Millisecond), len(unbounded), dInf.Round(time.Millisecond))
	}
}

